playStorePolicies.invasiveSnippet:
// app/build.gradle.kts — Release BuildType
buildTypes {
    release {
        isMinifyEnabled = true          // War: false
        isShrinkResources = true        // War: false
        proguardFiles(
            getDefaultProguardFile("proguard-android-optimize.txt"),
            "proguard-rules.pro"
        )
    }
}

// proguard-rules.pro — Pflicht-Regeln ergänzen:
// Room
-keep class * extends androidx.room.RoomDatabase
-keep @androidx.room.Entity class *
-keepattributes *Annotation*

// Hilt
-keep class dagger.hilt.** { *; }
-keep class javax.inject.** { *; }
-keep @dagger.hilt.android.AndroidEntryPoint class *

// Firebase
-keep class com.google.firebase.** { *; }
-dontwarn com.google.firebase.**

// Play Billing
-keep class com.android.billingclient.** { *; }
-dontwarn com.android.billingclient.**

// Kotlin Serialization (falls verwendet)
-keepattributes *Annotation*, InnerClasses
-dontnote kotlinx.serialization.AnnotationsKt

// Gson (falls verwendet)
-keepattributes Signature
-keepattributes *Annotation*

